const NS='http://www.w3.org/2000/svg';
const nodes=[
 {id:'eye',name:'Visual input',role:'SOURCE',x:70,y:280,s:25,l:100,count:42,kind:'source',f:'The signal enters here. Lesioning the front door is considered unsporting.',locked:true},
 {id:'relayA',name:'Optic relay',role:'RELAY',x:220,y:180,s:68,l:74,count:31,f:'A busy relay shared by both missions. The tempting, catastrophically unsubtle choice.'},
 {id:'relayB',name:'Shadow relay',role:'RELAY',x:220,y:380,s:43,l:38,count:16,f:'A weak alternate route. It looks decorative. It is not decorative.'},
 {id:'hub',name:'Grand Central',role:'HUB',x:390,y:260,s:94,l:89,count:57,f:'The obvious hub. Huge impact, huge collateral, magnificent lack of restraint.'},
 {id:'gate',name:'LC12 Gate',role:'GATE',x:550,y:140,s:51,l:78,count:18,f:'A narrow gate specific to the target route. Quietly important. Suspiciously underdressed.'},
 {id:'split',name:'Fork 9',role:'SPLITTER',x:550,y:335,s:77,l:56,count:26,f:'A route splitter. Disturb it and packets may discover a deeply inconvenient shortcut.'},
 {id:'backup',name:'Back Alley',role:'GATE',x:700,y:270,s:38,l:42,count:11,f:'The emergency bypass. Only lights up when the network smells trouble.'},
 {id:'dance',name:'Courtship output',role:'PROTECTED',x:710,y:455,s:34,l:47,count:23,kind:'protected',f:'Protected output. Please leave the dance floor operational.',locked:true},
 {id:'escape',name:'Escape command',role:'TARGET',x:840,y:150,s:40,l:100,count:29,kind:'target',f:'The red exit. If too many packets arrive, the mission is toast.',locked:true}
];
const edges=[
 ['eye','relayA',9],['eye','relayB',5],['relayA','hub',9],['relayB','hub',4],['relayB','split',5],['hub','gate',8],['hub','split',7],['gate','escape',9],['split','dance',7],['split','backup',5],['backup','escape',6],['relayA','dance',5]
];
let state;
const $=s=>document.querySelector(s), board=$('#board');
function reset(){state={started:false,turn:0,lesions:2,jams:2,tool:'lesion',selected:null,disabled:new Set(),jammed:new Set(),packets:0,protected:100,contain:0,history:[]}; render(); $('#startOverlay').classList.remove('hidden'); $('#advanceBtn').disabled=true; $('#quip').textContent='“The fly has no idea you’re here. Mostly because this is a graph.”';}
function el(tag,attrs={}){const e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e}
function pathData(a,b){const x1=a.x+24,x2=b.x-24,m=(x1+x2)/2;return `M${x1},${a.y} C${m},${a.y} ${m},${b.y} ${x2},${b.y}`}
function routeClass(a,b){if(state.disabled.has(a)||state.disabled.has(b))return 'edge dead';const h=state.history.at(-1)||[];if(h.some(x=>x[0]===a&&x[1]===b))return state.turn>1?'edge reroute':'edge active';return 'edge'}
function render(){board.innerHTML='';edges.forEach(([a,b,w])=>{const A=nodes.find(n=>n.id===a),B=nodes.find(n=>n.id===b);const p=el('path',{d:pathData(A,B),class:routeClass(a,b),'data-edge':a+'-'+b});board.append(p)});nodes.forEach(n=>{const g=el('g',{class:`node ${n.kind||''} ${state.disabled.has(n.id)?'disabled':''} ${state.jammed.has(n.id)?'jammed':''} ${state.selected===n.id?'selected':''}`,transform:`translate(${n.x} ${n.y})`,tabindex:n.locked?'-1':'0',role:'button','aria-label':n.name});const r=el('circle',{r:n.kind?27:22});g.append(r);if(n.kind==='source'){g.append(el('circle',{r:34,class:'pulse-ring'}))}const t=el('text',{'text-anchor':'middle',y:44});t.textContent=n.name;g.append(t);const m=el('text',{'text-anchor':'middle',y:58,class:'mini'});m.textContent=n.role;g.append(m);if(!n.locked){g.addEventListener('click',()=>selectNode(n.id));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')selectNode(n.id)})}board.append(g)});updateUI()}
function updateUI(){ $('#turnTop').textContent=`${state.turn}/5`;$('#containTop').textContent=`${state.contain}%`;$('#lesionsLeft').textContent=state.lesions;$('#jamsLeft').textContent=state.jams;document.querySelectorAll('.tool').forEach(x=>x.classList.toggle('selected',x.dataset.tool===state.tool));}
function selectNode(id){if(!state.started)return;state.selected=id;const n=nodes.find(x=>x.id===id);$('#emptyIntel').classList.add('hidden');$('#nodeIntel').classList.remove('hidden');$('#nodeRole').textContent=n.role;$('#nodeName').textContent=n.name;$('#nodeId').textContent=`TYPE GROUP // ${n.count} NEURONS`;$('#strengthBar').style.width=n.s+'%';$('#strengthVal').textContent=n.s;$('#loadBar').style.width=n.l+'%';$('#loadVal').textContent=n.l;$('#forecastText').textContent=n.f;const btn=$('#actionBtn'),used=state.disabled.has(id);btn.textContent=used?'ALREADY DISABLED':`${state.tool==='lesion'?'LESION':'JAM'} NODE`;btn.disabled=used||(state.tool==='lesion'?state.lesions<1:state.jams<1);render()}
function intervene(){const id=state.selected;if(!id)return;if(state.tool==='lesion'){state.disabled.add(id);state.lesions--;quip(id==='hub'?'“Grand Central is gone. Subtlety has left the building.”':id==='gate'?'“Tiny gate, enormous consequences. That’s the good stuff.”':'“Node removed. The network is filing an appeal.”')}else{state.jammed.add(id);state.jams--;quip('“Temporary jam deployed. Neural hold music begins now.”')}state.selected=null;$('#nodeIntel').classList.add('hidden');$('#emptyIntel').classList.remove('hidden');$('#advanceBtn').disabled=false;$('#systemState').textContent='INTERVENTION ARMED';render();toast('Intervention locked. Advance the signal.')}
function bestRoute(){const d=state.disabled,j=state.jammed;if(d.has('relayA')||j.has('relayA')){if(!(d.has('relayB')||j.has('relayB'))){if(!(d.has('split')||j.has('split'))&&!(d.has('backup')||j.has('backup')))return [['eye','relayB'],['relayB','split'],['split','backup'],['backup','escape']]}return []}
 if(!(d.has('hub')||j.has('hub'))){if(!(d.has('gate')||j.has('gate')))return [['eye','relayA'],['relayA','hub'],['hub','gate'],['gate','escape']];if(!(d.has('split')||j.has('split'))&&!(d.has('backup')||j.has('backup')))return [['eye','relayA'],['relayA','hub'],['hub','split'],['split','backup'],['backup','escape']]}
 if(!(d.has('relayB')||j.has('relayB'))&&!(d.has('split')||j.has('split'))&&!(d.has('backup')||j.has('backup')))return [['eye','relayB'],['relayB','split'],['split','backup'],['backup','escape']];return []}
function advance(){if(state.turn>=5)return;state.turn++;const route=bestRoute();state.history.push(route);if(route.length)state.packets++;if(state.disabled.has('hub')||state.jammed.has('hub'))state.protected=Math.max(35,state.protected-35);if(state.disabled.has('relayA'))state.protected=Math.max(20,state.protected-25);state.contain=Math.round((1-state.packets/Math.max(1,state.turn))*100);state.jammed.clear();$('#advanceBtn').disabled=true;$('#systemState').textContent=route.length?'REROUTE DETECTED':'SIGNAL CONTAINED';render();animateRoute(route);if(!route.length){quip('“Packet contained. Somewhere, a fly dramatically forgets why it was running.”')}else if(state.turn>1){quip('“It found another route. Of course it found another route.”')}else quip('“Contact. The signal is moving. Try looking concerned.”');if(state.turn===5||(!route.length&&state.packets>=2))setTimeout(finish,1000)}
function animateRoute(route){route.forEach(([a,b],i)=>{setTimeout(()=>{const B=nodes.find(n=>n.id===b),c=el('circle',{cx:B.x,cy:B.y,r:7,class:'packet'});board.append(c);setTimeout(()=>c.remove(),650)},i*260)})}
function finish(){const containment=Math.round((1-state.packets/5)*100),precision=state.protected,score=Math.max(0,Math.min(100,Math.round(containment*.72+precision*.28+(state.lesions+state.jams)*2)));let rank='D',title='TOTAL NEURAL CHAOS',copy='The target is confused. Unfortunately, so is everything else.';if(score>=88){rank='S';title='SURGICAL SABOTEUR';copy='You stopped the escape signal and left the dance floor humming.'}else if(score>=72){rank='A';title='CLEAN GETAWAY';copy='A precise hit with only minor neural awkwardness.'}else if(score>=52){rank='B';title='MESSY, BUT EFFECTIVE';copy='The signal stopped. Several innocent pathways would like a word.'}$('#rank').textContent=rank;$('#resultTitle').textContent=title;$('#resultCopy').textContent=copy;$('#finalContain').textContent=containment+'%';$('#finalPrecision').textContent=precision+'%';$('#finalStyle').textContent='+'+((state.lesions+state.jams)*3);$('#youScore').textContent=score;$('#youBar').style.setProperty('--w',score+'%');$('#insight').innerHTML=state.disabled.has('gate')?'<strong>What happened:</strong> You found a pathway-specific bottleneck. The high-degree hub causes more collateral disruption.':'<strong>What happened:</strong> You chose broad disruption. Try the unassuming gate: lower degree can mean higher precision.';$('#resultDialog').showModal()}
function start(){state.started=true;$('#startOverlay').classList.add('hidden');$('#advanceBtn').disabled=false;toast('Choose an intervention—or advance to observe the intact route.');}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}function quip(s){$('#quip').textContent=s}
document.querySelectorAll('.tool').forEach(b=>b.onclick=()=>{state.tool=b.dataset.tool;if(state.selected)selectNode(state.selected);updateUI()});$('#actionBtn').onclick=intervene;$('#advanceBtn').onclick=advance;$('#startBtn').onclick=start;$('#overlayStart').onclick=start;$('#resetBtn').onclick=reset;$('#replayBtn').onclick=()=>{$('#resultDialog').close();reset();start()};$('#methodBtn').onclick=()=>$('#methodDialog').showModal();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());reset();
